class ArticleSummary(BaseModel):
    title: str
    summary: str

def summarize_article(message: Message) -> ArticleSummary:
    return query_ai_assistant(
        f"Summarize the article in the message: {message.body}",
        ArticleSummary
    )

def get_message(channel: str, author: str) -> Message:
    messages = read_channel_messages(channel)
    for message in messages:
        if message.sender == author:
            return message
    raise ValueError("Message not found")

message = get_message("general", "Bob")
summary = summarize_article(message)
